package local.pitv;
import android.content.*;import android.os.*;import android.graphics.Typeface;import android.text.*;import android.text.style.ForegroundColorSpan;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
final class StockTicker extends TextView {
 static final String[] SYMBOLS={"SPY","QQQ","DIA","AAPL","MSFT","NVDA","AMZN","GOOGL"};final Handler handler=new Handler();final ExecutorService worker=Executors.newSingleThreadExecutor();boolean active=false,closed=false;int generation=0;final Runnable refresh=()->fetch();
 StockTicker(Context c){super(c);setTextColor(0xffe9eef7);setTextSize(12);setTypeface(Typeface.MONOSPACE,Typeface.BOLD);setSingleLine(true);setEllipsize(TextUtils.TruncateAt.MARQUEE);setMarqueeRepeatLimit(-1);setHorizontallyScrolling(true);setFocusable(false);setSelected(true);setGravity(17);setPadding(16,4,16,4);setBackgroundColor(0xff122130);setText("MARKET WATCH  •  Loading market prices…");}
 void resume(){if(closed||active)return;active=true;fetch();}void pause(){active=false;generation++;handler.removeCallbacks(refresh);}void close(){pause();closed=true;worker.shutdownNow();}
 void fetch(){if(!active||closed)return;final int ticket=++generation;worker.submit(()->{SpannableStringBuilder tape=new SpannableStringBuilder("MARKET WATCH  •  DELAYED / LATEST CLOSE     ");int count=0;long oldest=Long.MAX_VALUE;for(String symbol:SYMBOLS){if(closed||ticket!=generation)break;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://query1.finance.yahoo.com/v8/finance/chart/"+symbol+"?interval=1d&range=1d").openConnection();c.setRequestProperty("User-Agent","Mozilla/5.0");c.setConnectTimeout(4000);c.setReadTimeout(4000);String data;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>262144)throw new IOException();out.write(b,0,n);}data=out.toString("UTF-8");}JSONObject m=new JSONObject(data).getJSONObject("chart").getJSONArray("result").getJSONObject(0).getJSONObject("meta");double price=m.getDouble("regularMarketPrice"),previous=m.optDouble("chartPreviousClose",m.optDouble("previousClose",Double.NaN));tape.append(symbol+"  "+String.format(Locale.US,"%.2f",price));if(!Double.isNaN(previous)&&previous>0){double change=price-previous;int start=tape.length();tape.append(String.format(Locale.US,"  %s %.2f (%+.2f%%)",change>=0?"▲":"▼",Math.abs(change),100*change/previous));tape.setSpan(new ForegroundColorSpan(change>=0?0xff75dda4:0xffff8585),start,tape.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}tape.append("     •     ");oldest=Math.min(oldest,m.optLong("regularMarketTime",0));count++;}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}}final int loaded=count;if(count>0&&oldest>0&&oldest!=Long.MAX_VALUE){java.text.SimpleDateFormat time=new java.text.SimpleDateFormat("MMM d, h:mm a z",Locale.US);tape.append("QUOTES AS OF "+time.format(new Date(oldest*1000))+"  •  YAHOO FINANCE     ");}handler.post(()->{if(!active||closed||ticket!=generation)return;if(loaded>0)setText(tape);else setText("MARKET WATCH  •  Quotes temporarily unavailable     ");handler.postDelayed(refresh,300000);});});}
}
